example.code:
n = int(input())
for i in range(n):
    a = int(input())
    if a > 0:
        print(f"Number {i + 1}: {a} is positive")
    elif a < 0:
        print(f"Number {i + 1}: {a} is negative")
    else:
        print(f"Number {i + 1}: {a} is zero")
    if a >= 0:
        print(f"  {a} >= 0, so the first line: |a| = a = {a}")
    else:
        print(f"  {a} < 0, so the second line: |a| = -a = {-a}")
    print(f"  abs() agrees: {abs(a)}")

