example.code:
n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    print(f"Pair {i + 1}: a = {a}, b = {b}")
    if b > 0:
        print(f"  {a} + ({b}): start at {a}, move {b} right, land on {a + b}")
    elif b < 0:
        print(f"  {a} + ({b}): start at {a}, move {abs(b)} left, land on {a + b}")
    else:
        print(f"  {a} + ({b}): start at {a} and stay put")
    print(f"  {a} - ({b}) = {a} + ({-b}) = {a + (-b)}, adding the opposite")
    print(f"  distance between them: |{a} - ({b})| = {abs(a - b)}")

