example.code:
n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    print(f"Pair {i + 1}: {a} * {b}")
    if a == 0:
        sign = "zero"
    elif b == 0:
        sign = "zero"
    elif (a < 0) == (b < 0):
        sign = "positive"
    else:
        sign = "negative"
    size = abs(a) * abs(b)
    print(f"  sizes: {abs(a)} * {abs(b)} = {size}, sign: {sign}")
    if sign == "negative":
        product = -size
    else:
        product = size
    print(f"  by the rule: {product}, and Python agrees: {product == a * b}")

